
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lc_blypr_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lc_blypr", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.188768853056457e+00, -4.106521831752162e+00, -3.991317314610164e+00, -3.831817918553468e+00, -3.614652044119687e+00, -3.325944161886695e+00, -2.954887697802110e+00, -2.499942628161018e+00, -1.976222162482236e+00, -1.417006570526820e+00, -8.736367419561485e-01, -5.528903792809542e-01, -4.599704477204175e-01, -3.499727487870216e-01, -2.047515167087353e-01, -7.648322846518997e-02, -1.229650272330957e-02, -4.325472245489557e-04, -3.958133880687926e-06, -5.521437383107574e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


